import React, { useState } from 'react';
import KVKKText from './KVKKText';
import '../styles/form/RegistrationForm.css';

const RegistrationForm = ({ onSubmit }) => {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '', // E-posta alanı ekledik
    phoneNumber: '',
    kvkkApproved: false,
    emailConsent: false // E-posta ile bilgilendirme izni ekledik
  });
  
  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({
      ...formData,
      [name]: type === 'checkbox' ? checked : value
    });
    
    // Hata mesajını temizle
    if (errors[name]) {
      setErrors({
        ...errors,
        [name]: ''
      });
    }
  };

  const validateForm = () => {
    const newErrors = {};
    
    // Ad doğrulama
    if (!formData.firstName.trim()) {
      newErrors.firstName = 'Ad alanı zorunludur';
    }
    
    // Soyad doğrulama
    if (!formData.lastName.trim()) {
      newErrors.lastName = 'Soyad alanı zorunludur';
    }
    
    // E-posta doğrulama
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!formData.email) {
      newErrors.email = 'E-posta alanı zorunludur';
    } else if (!emailRegex.test(formData.email)) {
      newErrors.email = 'Geçerli bir e-posta adresi girin';
    }
    
    // Telefon numarası doğrulama (Türkiye için)
    const phoneRegex = /^(05)[0-9][0-9][0-9]{7}$/;
    if (!formData.phoneNumber) {
      newErrors.phoneNumber = 'Telefon numarası alanı zorunludur';
    } else if (!phoneRegex.test(formData.phoneNumber.replace(/\s/g, ''))) {
      newErrors.phoneNumber = 'Geçerli bir telefon numarası girin (05xx xxx xx xx)';
    }
    
    // KVKK onayı doğrulama
    if (!formData.kvkkApproved) {
      newErrors.kvkkApproved = 'Devam etmek için KVKK metnini onaylamanız gerekmektedir';
    }
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (validateForm()) {
      onSubmit(formData);
    }
  };

  return (
    <div className="registration-form-container">
      <h2 className="registration-title">Çekiliş Kayıt Formu</h2>
      <form onSubmit={handleSubmit}>
      <div className="form-group">
        <label htmlFor="firstName">Ad</label>
        <input
          type="text"
          id="firstName"
          name="firstName"
          className="form-control"
          value={formData.firstName}
          onChange={handleChange}
        />
        {errors.firstName && <div className="error">{errors.firstName}</div>}
      </div>
      
      <div className="form-group">
        <label htmlFor="lastName">Soyad</label>
        <input
          type="text"
          id="lastName"
          name="lastName"
          className="form-control"
          value={formData.lastName}
          onChange={handleChange}
        />
        {errors.lastName && <div className="error">{errors.lastName}</div>}
      </div>
      
      <div className="form-group">
        <label htmlFor="email">E-posta Adresi</label>
        <input
          type="email"
          id="email"
          name="email"
          className="form-control"
          placeholder="ornek@email.com"
          value={formData.email}
          onChange={handleChange}
        />
        {errors.email && <div className="error">{errors.email}</div>}
      </div>
      
      <div className="form-group">
        <label htmlFor="phoneNumber">Telefon Numarası</label>
        <input
          type="tel"
          id="phoneNumber"
          name="phoneNumber"
          className="form-control"
          placeholder="05xx xxx xx xx"
          value={formData.phoneNumber}
          onChange={handleChange}
        />
        {errors.phoneNumber && <div className="error">{errors.phoneNumber}</div>}
      </div>
      
      <div className="form-group">
        <KVKKText />
        
        <div className="checkbox-container">
          <input
            type="checkbox"
            id="kvkkApproved"
            name="kvkkApproved"
            checked={formData.kvkkApproved}
            onChange={handleChange}
          />
          <label htmlFor="kvkkApproved">
            Kişisel verilerimin, yukarıda belirtilen amaçlar doğrultusunda işlenmesini kabul ediyorum.
          </label>
        </div>
        {errors.kvkkApproved && <div className="error">{errors.kvkkApproved}</div>}
        
        <div className="checkbox-container">
          <input
            type="checkbox"
            id="emailConsent"
            name="emailConsent"
            checked={formData.emailConsent}
            onChange={handleChange}
          />
          <label htmlFor="emailConsent">
            Konya Teknik Üniversitesi Kimya Mühendisliği Topluluğu'nun etkinlikleri ve duyuruları hakkında e-posta ile bilgilendirilmeyi kabul ediyorum.
          </label>
        </div>
      </div>
      
      <button type="submit" className="submit-button">
        Çekilişe Katıl
      </button>
      </form>
    </div>
  );
};

export default RegistrationForm;
