import { runTransaction, doc } from 'firebase/firestore';
import { db } from '../firebase/config';

/**
 * Daha güvenilir rastgele sayı üreteci.
 * @param {number} max - Maksimum değer (hariç)
 * @returns {number} - 0 ile max arasında rastgele bir sayı
 */
export const getRandomIndex = (max) => {
  return Math.floor(Math.random() * max);
};

/**
 * Bir diziyi rastgele karıştırır (Fisher-Yates algoritması)
 * @param {Array} array - Karıştırılacak dizi
 * @returns {Array} - Karıştırılmış dizi
 */
export const shuffleArray = (array) => {
  const newArray = [...array];
  for (let i = newArray.length - 1; i > 0; i--) {
    const j = getRandomIndex(i + 1);
    [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
  }
  return newArray;
};

/**
 * Ödülleri öncelik değerine göre sıralar
 * @param {Array} prizes - Ödül listesi
 * @returns {Array} - Önceliğe göre sıralanmış ödül listesi
 */
export const sortPrizesByPriority = (prizes) => {
  return [...prizes].sort((a, b) => {
    // Yüksek öncelik değeri olan ödüller önce gelsin
    const priorityA = a.priority || 1;
    const priorityB = b.priority || 1;
    return priorityB - priorityA;
  });
};

/**
 * Katılımcı ve ödül güncellemelerini tek bir transaction içinde gerçekleştirir
 * @param {Array} participantUpdates - Katılımcı güncellemelerinin listesi [{id, data}]
 * @param {Array} prizeUpdates - Ödül güncellemelerinin listesi [{id, data}]
 * @returns {Promise<object>} - İşlem sonucu
 */
export const updateDrawResultsWithTransaction = async (participantUpdates, prizeUpdates) => {
  try {
    await runTransaction(db, async (transaction) => {
      // Katılımcı güncellemeleri
      for (const update of participantUpdates) {
        const participantRef = doc(db, 'participants', update.id);
        transaction.update(participantRef, update.data);
      }
      
      // Ödül güncellemeleri
      for (const update of prizeUpdates) {
        const prizeRef = doc(db, 'prizes', update.id);
        transaction.update(prizeRef, update.data);
      }
    });
    
    return { success: true };
  } catch (error) {
    console.error('Çekiliş sonuçları güncellenirken hata:', error);
    return { success: false, error: error.message };
  }
};

/**
 * Çekiliş için kullanılabilecek hata mesajlarını hazırlar
 * @param {Error} error - Hata nesnesi
 * @returns {string} - Kullanıcı dostu hata mesajı
 */
export const getDrawErrorMessage = (error) => {
  if (!error) return 'Bilinmeyen bir hata oluştu.';
  
  // Firestore hata kodlarına göre özelleştirilmiş mesajlar
  if (error.code === 'permission-denied') {
    return 'Çekiliş yapma yetkiniz bulunmuyor. Lütfen yönetici ile iletişime geçin.';
  } else if (error.code === 'unavailable') {
    return 'Veritabanına erişimde sorun yaşanıyor. Lütfen internet bağlantınızı kontrol edin ve tekrar deneyin.';
  } else if (error.code === 'cancelled') {
    return 'İşlem iptal edildi. Lütfen tekrar deneyin.';
  } else if (error.code === 'data-loss') {
    return 'Veri kaybı yaşandı. Lütfen yönetici ile iletişime geçin.';
  }
  
  return `Çekiliş sırasında bir hata oluştu: ${error.message}. Lütfen tekrar deneyin.`;
};
