import React, { useState } from 'react';

const PasswordModal = ({ isOpen, onClose, onConfirm, title, message }) => {
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (password === 'adminrx2025') { // Örnek şifre - daha güvenli bir yöntem kullanılabilir
      onConfirm();
      onClose();
      setPassword('');
      setError('');
    } else {
      setError('Hatalı şifre!');
    }
  };

  if (!isOpen) return null;

  return (
    <div className="modal-overlay" style={overlayStyle}>
      <div className="modal-content" style={modalStyle}>
        <div className="modal-header" style={headerStyle}>
          <h2 style={{ margin: 0 }}>{title || 'Şifre Doğrulama'}</h2>
          <button onClick={onClose} style={closeButtonStyle}>
            &times;
          </button>
        </div>
        
        <div className="modal-body" style={bodyStyle}>
          <p>{message || 'Bu işlemi gerçekleştirmek için lütfen admin şifresini girin.'}</p>
          
          <form onSubmit={handleSubmit}>
            <div style={formGroupStyle}>
              <label htmlFor="password" style={labelStyle}>Şifre:</label>
              <input
                type="password"
                id="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                style={inputStyle}
                autoFocus
                required
              />
            </div>
            
            {error && <div style={errorStyle}>{error}</div>}
            
            <div style={buttonContainerStyle}>
              <button type="button" onClick={onClose} style={buttonStyle}>
                İptal
              </button>
              <button type="submit" style={submitButtonStyle}>
                Onayla
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

// Stil tanımlamaları
const overlayStyle = {
  position: 'fixed',
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: 'rgba(0, 0, 0, 0.6)',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  zIndex: 1000
};

const modalStyle = {
  backgroundColor: 'white',
  borderRadius: '8px',
  boxShadow: '0 2px 10px rgba(0, 0, 0, 0.3)',
  width: '90%',
  maxWidth: '400px',
  maxHeight: '90vh',
  overflow: 'auto',
  position: 'relative'
};

const headerStyle = {
  borderBottom: '1px solid #eee',
  padding: '15px 20px',
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center'
};

const bodyStyle = {
  padding: '20px'
};

const formGroupStyle = {
  marginBottom: '15px'
};

const labelStyle = {
  display: 'block',
  marginBottom: '5px',
  fontWeight: 'bold'
};

const inputStyle = {
  width: '100%',
  padding: '8px 12px',
  borderRadius: '4px',
  border: '1px solid #ddd',
  fontSize: '16px'
};

const buttonContainerStyle = {
  display: 'flex',
  justifyContent: 'flex-end',
  gap: '10px',
  marginTop: '20px'
};

const buttonStyle = {
  padding: '8px 15px',
  borderRadius: '4px',
  border: '1px solid #ddd',
  backgroundColor: '#f4f4f4',
  cursor: 'pointer'
};

const submitButtonStyle = {
  ...buttonStyle,
  backgroundColor: '#007bff',
  color: 'white',
  border: 'none'
};

const closeButtonStyle = {
  background: 'none',
  border: 'none',
  fontSize: '24px',
  cursor: 'pointer',
  padding: '0 5px',
  lineHeight: '1'
};

const errorStyle = {
  color: '#dc3545',
  fontSize: '14px',
  marginTop: '5px'
};

export default PasswordModal;