import React, { useState, useContext, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { ParticipantContext } from '../context/ParticipantContext';
import { PrizeContext } from '../context/PrizeContext';
import WinnerDisplay from '../components/WinnerDisplay';
import ConfettiEffect from '../components/ConfettiEffect';
import { 
  sortPrizesByPriority,
  shuffleArray,
  getRandomIndex,
  updateDrawResultsWithTransaction,
  getDrawErrorMessage
} from '../utils/drawUtils';
import { logger } from '../utils/logger';

const DrawPage = () => {
  const { participants, updateParticipant, refreshParticipants } = useContext(ParticipantContext);
  const { prizes, updatePrize, refreshPrizes } = useContext(PrizeContext);
  
  const [drawing, setDrawing] = useState(false);
  const [winners, setWinners] = useState([]);
  const [showConfetti, setShowConfetti] = useState(false);
  const [drawingComplete, setDrawingComplete] = useState(false);
  const [error, setError] = useState('');
  const [drawSettings, setDrawSettings] = useState({
    allowMultipleWins: false,
    sortByPriority: true,
    randomizePrizes: false
  });
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    // Verileri yenile
    const loadData = async () => {
      await refreshParticipants();
      await refreshPrizes();
    };

    loadData();
  }, [refreshParticipants, refreshPrizes]);

  // Çekiliş ayarlarını değiştirme işleyicisi
  const handleSettingChange = useCallback((e) => {
    const { name, checked } = e.target;
    setDrawSettings(prev => ({
      ...prev,
      [name]: checked
    }));
  }, []);

  // Çekiliş işlemini gerçekleştiren ana fonksiyon
  const conductDraw = async () => {
    if (participants.length === 0) {
      setError('Çekiliş için katılımcı bulunmamaktadır.');
      logger.warn('DRAW', 'Katılımcı olmadan çekiliş denemesi yapıldı');
      return;
    }

    setDrawing(true);
    setWinners([]);
    setError('');

    try {
      // İlerleme göstergesini sıfırla
      setProgress(0);
      const availableParticipants = [...participants];
      const drawnWinners = [];
      let allPrizesDrawn = true;

      // Ödülleri istenen sıralama kriterine göre hazırla
      let prizesToDraw = [...prizes];
      
      logger.draw.start({ 
        totalParticipants: participants.length,
        totalPrizes: prizes.length,
        settings: drawSettings 
      });
      
      // Önceliğe göre sıralama
      if (drawSettings.sortByPriority) {
        prizesToDraw = sortPrizesByPriority(prizesToDraw);
      }
      
      // Rastgele karıştırma (önceliğe göre sıralamadan sonra bile)
      if (drawSettings.randomizePrizes) {
        prizesToDraw = shuffleArray(prizesToDraw);
      }

      // Veritabanı güncellemeleri için toplu işlem listeleri
      const participantUpdates = [];
      const prizeUpdates = [];
      const totalPrizes = prizesToDraw.length;
      let processedPrizes = 0;

      // Her ödül için çekiliş yap
      for (const prize of prizesToDraw) {
        if (availableParticipants.length === 0) {
          allPrizesDrawn = false;
          break;
        }

        // Bu ödül için çekilecek kazanan sayısı
        const winnersCount = Math.min(prize.quantity, availableParticipants.length);
        const prizeWinners = [];

        for (let i = 0; i < winnersCount; i++) {
          // Rastgele bir katılımcı seç
          const randomIndex = getRandomIndex(availableParticipants.length);
          const winner = availableParticipants[randomIndex];
          
          // Çoklu kazanma seçeneği etkinleştirilmemişse, katılımcıyı listeden çıkar
          if (!drawSettings.allowMultipleWins) {
            availableParticipants.splice(randomIndex, 1);
          }
          
          // Kazananı listeye ekle
          prizeWinners.push({
            ...winner,
            prizeName: prize.name,
            prizeSponsor: prize.sponsor
          });

          // Kazanma bilgisini logla
          logger.draw.prizeAssigned(prize, winner);

          // Kazanan güncellemesini toplu işlem listesine ekle
          participantUpdates.push({
            id: winner.id,
            data: {
              isWinner: true,
              prize: prize.name
            }
          });
        }

        // Ödül güncellemesini toplu işlem listesine ekle
        const winnerIds = prizeWinners.map(winner => winner.id);
        prizeUpdates.push({
          id: prize.id,
          data: {
            winners: winnerIds
          }
        });
        
        // İlerleme durumunu güncelle
        processedPrizes++;
        setProgress(Math.floor((processedPrizes / totalPrizes) * 100));
        
        // Loglama: Ödül için çekiliş tamamlandı
        logger.info('DRAW', `${prize.name} ödülü için çekiliş tamamlandı: ${prizeWinners.length} kazanan belirlendi`, {
          prizeId: prize.id,
          totalWinners: prizeWinners.length
        });

        // Kazananları toplam listesine ekle
        drawnWinners.push(...prizeWinners);
      }

      // Tüm güncellemeleri tek transaction'da gerçekleştir
      const updateResult = await updateDrawResultsWithTransaction(
        participantUpdates, 
        prizeUpdates
      );
      
      if (!updateResult.success) {
        throw new Error(updateResult.error || 'Çekiliş sonuçları güncellenirken bir hata oluştu.');
      }
      
      // Kazananları ekrana yansıt ve konfeti göster
      setWinners(drawnWinners);
      setShowConfetti(true);
      setDrawingComplete(allPrizesDrawn);
      setProgress(100);
      
      // Çekiliş tamamlandı log kaydı
      logger.draw.complete({
        totalWinners: drawnWinners.length,
        allPrizesDrawn: allPrizesDrawn,
        remainingParticipants: availableParticipants.length
      });
      
      // 10 saniye sonra konfetiyi kapat
      setTimeout(() => {
        setShowConfetti(false);
      }, 10000);
    } catch (err) {
      console.error('Çekiliş sırasında hata oluştu:', err);
      logger.draw.error('Çekiliş sırasında hata', err);
      setError(getDrawErrorMessage(err));
    } finally {
      setDrawing(false);
    }
  };

  return (
    <div className="container">
      <div className="header">
        <h1>ReactXchem Çekiliş Sonuçları</h1>
      </div>

      {showConfetti && <ConfettiEffect />}

      <div className="card">
        <h2>Çekilişi Başlat</h2>
        
        {error && <div className="error">{error}</div>}
        
        <div style={{ marginBottom: '20px' }}>
          <p>
            Toplam Katılımcı Sayısı: <strong>{participants.length}</strong>
          </p>
          <p>
            Toplam Ödül Sayısı: <strong>{prizes.reduce((total, prize) => total + prize.quantity, 0)}</strong>
          </p>
        </div>
        
        {/* Çekiliş Ayarları */}
        <div className="draw-settings" style={{ marginBottom: '20px', padding: '15px', border: '1px solid #eee', borderRadius: '5px' }}>
          <h3 style={{ marginTop: 0 }}>Çekiliş Ayarları</h3>
          <div>
            <label style={{ display: 'flex', alignItems: 'center', marginBottom: '10px' }}>
              <input
                type="checkbox"
                name="allowMultipleWins"
                checked={drawSettings.allowMultipleWins}
                onChange={handleSettingChange}
                style={{ marginRight: '10px' }}
              />
              Bir kişi birden fazla ödül kazanabilsin
            </label>
            
            <label style={{ display: 'flex', alignItems: 'center', marginBottom: '10px' }}>
              <input
                type="checkbox"
                name="sortByPriority"
                checked={drawSettings.sortByPriority}
                onChange={handleSettingChange}
                style={{ marginRight: '10px' }}
              />
              Ödülleri öncelik değerine göre sırala (yüksek öncelikli önce)
            </label>
            
            <label style={{ display: 'flex', alignItems: 'center' }}>
              <input
                type="checkbox"
                name="randomizePrizes"
                checked={drawSettings.randomizePrizes}
                onChange={handleSettingChange}
                style={{ marginRight: '10px' }}
              />
              Ödülleri rastgele sırayla dağıt
            </label>
          </div>
        </div>
        
        {/* Çekiliş Butonları */}
        <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
          <button
            className="btn btn-accent"
            onClick={conductDraw}
            disabled={drawing || participants.length === 0}
          >
            {drawing ? 'Çekiliş Yapılıyor...' : drawingComplete ? 'Çekilişi Yenile' : 'Çekilişi Başlat'}
          </button>
          
          <Link to="/admin" className="btn">
            Yönetim Paneline Dön
          </Link>
        </div>
        
        {/* İlerleme Göstergesi */}
        {drawing && (
          <div style={{ marginBottom: '20px' }}>
            <div style={{ 
              width: '100%', 
              backgroundColor: '#e0e0e0', 
              borderRadius: '4px', 
              overflow: 'hidden',
              height: '20px'
            }}>
              <div style={{ 
                width: `${progress}%`, 
                height: '100%', 
                backgroundColor: '#4CAF50',
                transition: 'width 0.3s ease'
              }}></div>
            </div>
            <p style={{ textAlign: 'center', marginTop: '5px' }}>Çekiliş yapılıyor... %{progress}</p>
          </div>
        )}
        
        {/* Tamamlanmayan Çekiliş Uyarısı */}
        {winners.length > 0 && !drawingComplete && (
          <div style={{ 
            padding: '10px', 
            backgroundColor: '#fff3cd', 
            color: '#856404', 
            borderRadius: '4px',
            marginBottom: '20px',
            border: '1px solid #ffeeba' 
          }}>
            <p style={{ margin: '0' }}><strong>Uyarı:</strong> Katılımcı sayısı yetersiz olduğu için bazı ödüller dağıtılamadı!</p>
          </div>
        )}

        {winners.length > 0 && (
          <WinnerDisplay winners={winners} />
        )}
      </div>
    </div>
  );
};

export default DrawPage;